import java.util.*;

class Solution {
  public int maximumLength(int[] nums, int k) {
    // value -> longest good subsequence ending in that value, per number of changes used
    Map<Integer, int[]> ending = new HashMap<>();
    int[] best = new int[k + 1];
    int answer = 0;
    for (int value : nums) {
      int[] end = ending.computeIfAbsent(value, v -> new int[k + 1]);
      int[] current = new int[k + 1];
      for (int changes = 0; changes <= k; changes++) {
        current[changes] = end[changes] + 1;
        if (changes > 0) current[changes] = Math.max(current[changes], best[changes - 1] + 1);
      }
      for (int changes = 0; changes <= k; changes++) {
        end[changes] = Math.max(end[changes], current[changes]);
        best[changes] = Math.max(best[changes], current[changes]);
        answer = Math.max(answer, current[changes]);
      }
    }
    return answer;
  }
}
